Method.Implementation:
set tSc = $$$OK Set Editable=1,IsCheckedOut=1,UserCheckedOut="" Set filename=..ExternalName(InternalName) Write !, "Get status for: " _ filename Set IsInSourceControl = ((filename'="") && (##class(%File).Exists(filename))) If 'IsInSourceControl { Set Editable=1 Quit $$$OK }
If $data(^ItfSourceCtrl(2,InternalName)) { Set IsCheckedOut=1 Set UserCheckedOut= $GET(^ItfSourceCtrl(2,InternalName)) }
If IsCheckedOut,UserCheckedOut=..SvnUserName Set Editable=1
set tSc = ..OnBeforeLoad(InternalName) Write !, "GetStatus() IsInSourceControl: " _ IsInSourceControl Quit tSc

Write !, "Start OnBeforeLoad" Set ..SvnUserName = "lpjnaras" Set sc= $$$OK
Set ^ItfSourceCtrl(2,InternalName)=..SvnUserName
Set filename=..ExternalName(InternalName) If filename="" Quit $$$OK
#; If no file then skip the import If '##class(%File).Exists(filename) { Write !,"File ",filename," not found, skipping import" Quit $$$OK }
#; If the timestamp on the file is the same as the last time #; it was imported, then do nothing If ##class(%File).GetFileDateModified(filename)= $get(^ItfSourceCtrl(0,InternalName)) { Write !, "Timestamp on the file is the same as the last time" Quit $$$OK }
#; Call the function to do the load Set sc=$system.OBJ.Load(filename,"-l-d") If $$$ISOK(sc) { Write !,"Imported '",InternalName,"' from file '",filename,"'" Set ^ItfSourceCtrl(0,InternalName)=##class(%File).GetFileDateModified(filename) Set ^ItfSourceCtrl(1,InternalName)=##class(%RoutineMgr).TS(InternalName) } Else { Do $SYSTEM.Status.DecomposeStatus(sc,.errors,"d") }
Write !, "Done OnBeforeLoad" Quit sc

Set sc=$$$OK
Write !, "Start After Compile"
If $zconvert($piece(InternalName,".",$length(InternalName,".")),"l")="cls" {
	Set sc=..OnAfterSave(InternalName)
	If $$$ISERR(sc) Quit sc
}
Set other=$get(^ItfSourceCtrl(0,"ExtraItems",InternalName))
For i=1:1:$length(other,",") {
	Set item=$piece(other,",",i)
	If item'="" Set sc=..OnAfterSave(item) If $$$ISERR(sc) Quit
}
Write !, "Done After Compile"
Quit sc

 #; See if we have it checked out
 Set ..SvnUserName = "lpjnaras"
 Set file=..ExternalName(InternalName)

 Write !, "CheckIn: " _ ..SvnUserName _ " : Get " _ $GET(^ItfSourceCtrl(2,InternalName))
 If '$data(^ItfSourceCtrl(2,InternalName)) {
   Quit $$$ERROR($$$GeneralError,"You cannot check in an item you have not checked out")
 }
 If $GET(^ItfSourceCtrl(2,InternalName)) '= ..SvnUserName {
	 Write !, ^ItfSourceCtrl(2,InternalName) ,  "=" _ ..SvnUserName 
   Quit $$$ERROR($$$GeneralError,"User '"_ $GET(^ItfSourceCtrl(2,InternalName)) _"'has this item checked out")
 }
 // Check Time 
  #; If the timestamp on the file is the same as the last time
 #; it was imported, then do nothing
 If ##class(%File).GetFileDateModified(file)=
                   $get(^ItfSourceCtrl(0,InternalName)) {
	 Write !, "Timestamp on the file is the same as the last time"
   Quit $$$ERROR($$$GeneralError,"File is not modified,  will not check in the file")
 }
 set comment = ""
 Do ..ReadCommentFile(.comment)
 if (comment = "")
 {
	 Quit $$$ERROR($$$GeneralError,"You cannot check in without comment. Create C:\EnsembleSC\svnComment.txt")
 }
 #; Write out the latest version
 Set sc=..OnAfterSave(InternalName)
 If $$$ISERR(sc) Quit sc
 
 if ( ##class(%File).Exists(file) )
 {
	Set stat = ..CommitToSvn(file, comment,  ..SvnUserName)
	      
	if stat = 0
	{
         #; Remove the global to show that we have checked it in
         Kill ^ItfSourceCtrl(2,InternalName)
	}
 }
 Quit $$$OK


set stat = $$$ERROR(9100, "Could not add")

SET fileParts = $Length(fName, "/")
Write !, fileParts
FOR ind=1:1:fileParts
{
	set dirName = $PIECE(fName, "/", ind)
	if (ind = 1)
	{
		set fullPath = dirName
	}
	else
	{
	    set fullPath = fullPath _ "\" _ dirName
	}
	Set cmd = "svn cleanup " _ fullPath  ; a non-recursive commit (-N)
	Set stat = $ZF(-1, cmd)
	Set cmd = "svn --username " _usrNm _ " commit -N -m """ _ comment _ """ " _ fullPath  ; a non-recursive commit (-N)
	Set stat = $ZF(-1, cmd)
	Write !, cmd _ " - SVN STAT: " _ stat		
}

Quit stat

set stat = $$$ERROR(9100, "Could not add")
SET fullPath = ""
SET fileParts = $Length(fName, "/")
// Write !, fileParts
FOR ind=1:1:fileParts
{
	set dirName = $PIECE(fName, "/", ind)
	if (ind = 1)
	{
		set fullPath = dirName
	}
	else
	{
	set fullPath = fullPath _ "\" _ dirName
	}
	Set cmd = "svn info " _ fullPath
	Set stat = $ZF(-1, cmd)
	Write !, cmd _ " - SVN STAT: " _ stat
	If stat '= 0 	{
		Set cmd = "svn add " _ fullPath
	    Set stat = $ZF(-1, cmd)
	    Write !, cmd _ " - SVN STAT: " _ stat
	}
	
}

Quit stat

Write !, "Mapping Name"
If $data(^ItfSourceCtrl)'=11 
{
	Set src = ..setSources()
	Write !,"^ItfSourceCtrl is not setup so hooks will not work"
	Set src = $data(^ItfSourceCtrl) 
	Write !, "Sources set: " _ src
}	
If $data(^ItfSourceCtrl)'=11 Write !,"^ItfSourceCtrl is not setup so hooks will not work" Quit ""
	
// For an abstract document, use the GetOther() method to try to determine its "real" class
If ##class(%RoutineMgr).UserType(InternalName,.docclass,.doctype) {
	// Check for a real abstract document subclass (or GetOther() may not work)
	If $classmethod(docclass,"%IsA","%Studio.AbstractDocument") {
		// Grab the actual name
		Set actualName = $classmethod(docclass,"GetOther",InternalName)
		// The actualName is only valid if we get a single .cls as a result
		If actualName'[",",$ZCVT($P(actualName,".",$L(actualName,".")),"U")="CLS" {
			// We use what GetOther() gives us, thus Demo.Loan.FindRateProcess.bpl becomes Demo.Loan.FindRateProcess.cls
			Set InternalName = actualName
		}
	}
}	

If $$CheckProtect^%qccServer(InternalName) Quit ""
Set nam=$p(InternalName,".",1,$l(InternalName,".")-1),ext=$p(InternalName,".",$l(InternalName,".")),ext=$zcvt(ext,"u")
If nam="" Quit ""
If ext="PRJ",nam["Default_" Quit ""
If ext="CLS",$$$defClassKeyGet(nam,$$$cCLASSgeneratedby)'="" Quit ""
Set default=0
Set p=$order(^ItfSourceCtrl(ext,nam)) For  s p=$order(^ItfSourceCtrl(ext,p),-1) Quit:p=""  If $extract(nam,1,$length(p))=p,$data(^ItfSourceCtrl(ext,p),found) Quit
If $data(found)=0,$data(^ItfSourceCtrl(ext,"*"),found) Set default=1
If $data(found)=0 Quit ""
If InternalName["/" {
	Set InternalName=$extract(InternalName,$length(p)+1,*)
	Quit $translate(found_$translate(InternalName,"%","_"),"\","/")
}
If ext="CLS"||(ext="PRJ")||(##class(%RoutineMgr).UserType(InternalName)) Quit $translate(found_$translate(nam,".%","/")_".xml","\","/")
Quit $translate($g(found)_$tr(nam,"%"_$s(default:".",1:""),"_/")_".xml","\","/")

kill ^ItfSourceCtrl
set ^ItfSourceCtrl="C:\EnsembleSC\"
set ^ItfSourceCtrl("CLS","*")="cls\"
set sc=$$$OK
/****
&sql(declare SU1 cursor for
	select ID into :class 
	from %Dictionary.ClassDefinition where NOT (ID %STARTSWITH '%'))
&sql(open SU1)
for {
	&sql(fetch SU1)
	quit:SQLCODE
	set sc= Name(class_".CLS")
	Write !, class
	quit:'sc
}
****/
quit sc
